def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_d = 0
    opp_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1

    opp_rate = opp_d / n if n > 0 else 0.0

    if opp_rate > 0.8:
        return 'D'

    if opp_d == 0:
        if my_d == 0:
            if n >= 1:
                return 'D'
            return 'C'
        elif my_d == 1:
            if history[-1][0] == 'D':
                return 'C'
            else:
                return 'D'
        else:
            return 'D'

    last_my, last_opp = history[-1]

    if last_opp == 'D':
        if last_my == 'D':
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            if opp_rate < 0.3:
                return 'C'
            if rng.random() < 0.5:
                return 'C'
            return 'D'
    else:
        if last_my == 'D':
            if n < 95 and rng.random() < 0.8:
                return 'D'
            return 'C'
        else:
            if opp_rate > 0.3 and n < 95 and rng.random() < 0.2:
                return 'D'
            return 'C'
